import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"配置","description":"","frontmatter":{},"headers":[],"relativePath":"zh/configuration.md","filePath":"zh/configuration.md"}`),a={name:`zh/configuration.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to “配置”">​</a></h1><p>FaultDeck 没有配置文件 —— 一切都在进程启动时以 CLI 参数传入。下表默认值直接取自源码。</p><h2 id="faultdeck-agent" tabindex="-1">faultdeck-agent <a class="header-anchor" href="#faultdeck-agent" aria-label="Permalink to “faultdeck-agent”">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>--bind ADDR</code></td><td><code>127.0.0.1:7000</code></td><td>TCP 监听地址</td></tr><tr><td><code>--token TOKEN</code></td><td>不设 → 鉴权关闭</td><td>设置后每个请求行必须以 <code>&lt;token&gt; </code> 开头</td></tr><tr><td><code>--interface IFACE</code></td><td><code>eth0</code></td><td><code>tc</code> 适配器操作的网卡</td></tr><tr><td><code>--management CIDR</code></td><td>空</td><td>可重复;保护网段,重叠即拒绝注入</td></tr><tr><td><code>--iptables PATH</code></td><td>无</td><td><code>disconnect</code> 必需;缺失时 agent 应答 <code>iptables missing</code></td></tr></tbody></table><p>编译期常量(不可配置):</p><table tabindex="0"><thead><tr><th>常量</th><th>值</th><th>位置</th></tr></thead><tbody><tr><td>请求载荷上限</td><td>64 KiB</td><td><code>faultdeck_agent::MAX_INJECTION_BYTES</code></td></tr><tr><td>引导 qdisc 句柄</td><td><code>100:</code></td><td><code>faultdeck_netem::PILOT_QDISC_HANDLE</code></td></tr><tr><td>netem qdisc 句柄</td><td><code>50:</code></td><td>适配器内部</td></tr><tr><td>最大延迟</td><td>86 400 000 ms(24 小时)</td><td><code>faultdeck_core::MAX_LATENCY_MS</code></td></tr><tr><td>iptables 链</td><td><code>FAULTDECK</code>,表 <code>mangle</code></td><td><code>faultdeck_agent::firewall::CHAIN</code></td></tr></tbody></table><p><code>AgentConfig</code>(参数背后的库结构体)支持 JSON 序列化,可编程构造。</p><h2 id="faultdeck-coordinator" tabindex="-1">faultdeck-coordinator <a class="header-anchor" href="#faultdeck-coordinator" aria-label="Permalink to “faultdeck-coordinator”">​</a></h2><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">faultdeck-coordinator</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [BIND]     </span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 默认 127.0.0.1:7001</span></span></code></pre></div><p>仅一个位置参数。状态(注册表、报告归档、路由)均在内存。</p><h2 id="faultdeck-cli" tabindex="-1">faultdeck(CLI) <a class="header-anchor" href="#faultdeck-cli" aria-label="Permalink to “faultdeck(CLI)”">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>适用</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>--host</code></td><td>所有 <code>remote</code> 子命令</td><td>必填</td><td>agent 地址</td></tr><tr><td><code>--port</code></td><td>所有 <code>remote</code> 子命令</td><td><code>7000</code></td><td>agent 端口</td></tr><tr><td><code>--token</code></td><td>所有 <code>remote</code> 子命令</td><td>无</td><td>前置到请求行</td></tr><tr><td><code>--fault</code></td><td><code>inject</code></td><td>必填</td><td><code>latency</code> | <code>loss</code> | <code>disconnect</code></td></tr><tr><td><code>--destination</code></td><td><code>inject</code></td><td>必填</td><td>IPv4 CIDR</td></tr><tr><td><code>--port-spec</code></td><td><code>inject</code></td><td>无</td><td>可选目的端口匹配</td></tr><tr><td><code>--milliseconds</code></td><td><code>inject --fault latency</code></td><td>该故障必需</td><td>延迟毫秒</td></tr><tr><td><code>--percent</code></td><td><code>inject --fault loss</code></td><td>该故障必需</td><td>丢包百分比</td></tr><tr><td><code>--scenario-name</code></td><td><code>inject</code></td><td><code>&quot;scenario&quot;</code></td><td>报告标签</td></tr><tr><td><code>--report-json</code></td><td><code>inject</code></td><td>无</td><td>本地写 JSON 报告</td></tr><tr><td><code>--report-html</code></td><td><code>inject</code></td><td>无</td><td>本地写 HTML 报告</td></tr></tbody></table><p>没有环境变量、没有配置文件查找,守护进程也没有上述参数之外的选项。</p>`,13)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};